import re
import datetime
from typing import Any


def od_data(row: Any) -> dict[str, Any]:
    return dict((row or {}).get("data") or {})


def od_text(value: Any) -> str:
    return str(value).strip() if value is not None else ""


def od_link_ids(row: Any, field: str) -> list[str]:
    out: list[str] = []
    for ref in ((row or {}).get("links") or {}).get(field) or []:
        if isinstance(ref, dict) and ref.get("id"):
            out.append(str(ref["id"]))
        elif isinstance(ref, str):
            out.append(ref)
    return out


def od_now() -> str:
    return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat()


order_id = params["order_id"]
note = od_text(params.get("note")) or "Order processed by Order Desk."
found = api.records.get(type_slug="od_orders", record_id=order_id) or {}
order: dict[str, Any] = dict(found.get("record") or {})
ticket_ids = od_link_ids(order, "ticket")
closed = False
ticket_number = ""
if ticket_ids:
    got = api.records.get(type_slug="od_tickets", record_id=ticket_ids[0]) or {}
    ticket: dict[str, Any] = dict(got.get("record") or {})
    ticket_number = od_text(od_data(ticket).get("ticket_number"))
    if od_text(od_data(ticket).get("ticket_status")) != "closed":
        api.records.update(type_slug="od_tickets", record_id=ticket_ids[0], record={"data": {"ticket_status": "closed", "resolved_on": od_now(), "close_note": (od_text(order.get("title")) + ": " + note)[:500]}})
    closed = True
